import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2017-APR-27 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-APR-27 :: Ceph Performance Weekly","date":"2017-05-17T00:00:00.000Z","updated":"2017-05-17T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","代码审查","问题解决"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-APR-27_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-APR-27_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),t={name:"posts/2017/2017-APR-27_-_-_Ceph_Performance_Weekly.md"};function o(h,e,s,n,d,p){return l(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（未提及具体日期）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>Paige（主持人）、Mark、Alan、Mercia、John、Andrey、Igor、Victor、Josh等。</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Ceph分布式存储系统开发讨论，包括功能请求、代码审查、性能优化、问题解决等。</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><p><strong>1. 功能请求与代码审查</strong></p><ul><li>讨论了discard功能的实现和性能问题，决定暂时不启用。</li><li>讨论了数据上传限制的实现和性能影响，决定进一步研究。</li><li>讨论了strata选项清理的pull request，认为已完成或接近完成。</li><li>讨论了多个编码优化pull request，包括避免重复CPU计算、减少锁竞争等。</li><li>讨论了性能优化方案，如减少锁获取、同步路径上下文切换延迟等。</li></ul><p><strong>2. 性能优化</strong></p><ul><li>讨论了统一限速策略的实现和性能影响，决定进一步研究。</li><li>讨论了磁盘队列深度对性能的影响，决定进一步研究。</li><li>讨论了同步写操作的性能问题，决定尝试同步写优化方案。</li><li>讨论了RocksDB在压缩过程中的性能问题，决定进一步研究。</li></ul><p><strong>3. 问题解决</strong></p><ul><li>讨论了XFS文件系统在高负载下的性能问题，决定进一步研究。</li><li>讨论了Ceph集群恢复的问题，决定进一步研究。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续研究discard功能、数据上传限制、统一限速策略、磁盘队列深度等问题。</li><li>尝试同步写优化方案。</li><li>进一步研究RocksDB在压缩过程中的性能问题。</li><li>进一步研究XFS文件系统在高负载下的性能问题。</li><li>进一步研究Ceph集群恢复的问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>各参会人员根据会议讨论结果，继续进行代码开发和性能优化工作。</li><li>定期召开会议，讨论项目进展和问题解决情况。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>邀请RocksDB开发人员参与讨论RocksDB性能问题。</li><li>邀请XFS文件系统开发人员参与讨论XFS文件系统性能问题。</li><li>邀请Ceph集群恢复开发人员参与讨论Ceph集群恢复问题。</li></ul><h3 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结：&quot;">​</a></h3><p>本次会议讨论了Ceph分布式存储系统的多个重要议题，包括功能请求、代码审查、性能优化、问题解决等。参会人员对讨论结果进行了深入分析和讨论，并制定了后续行动计划。本次会议对Ceph项目的开发进展具有重要意义。</p>',22)])])}const u=a(t,[["render",o]]);export{_ as __pageData,u as default};
